import sys

def roman_to_int_brute(s):
    total = 0
    i = 0
    while i < len(s):
        if s[i] == 'I':
            if i + 1 < len(s) and (s[i+1] == 'V' or s[i+1] == 'X'):
                total += (-1)
            else:
                total += 1
        elif s[i] == 'V':
            total += 5
        elif s[i] == 'X':
            if i + 1 < len(s) and (s[i+1] == 'L' or s[i+1] == 'C'):
                total += (-10)
            else:
                total += 10
        elif s[i] == 'L':
            total += 50
        elif s[i] == 'C':
            if i + 1 < len(s) and (s[i+1] == 'D' or s[i+1] == 'M'):
                total += (-100)
            else:
                total += 100
        elif s[i] == 'D':
            total += 500
        elif s[i] == 'M':
            total += 1000
        i += 1
    return total

if __name__ == '__main__':
    s = sys.stdin.readline().strip()
    print(roman_to_int_brute(s))

import sys

def roman_to_int_opt(s):
    mapping = {
        'I': 1, 'V': 5, 'X': 10, 'L': 50,
        'C': 100, 'D': 500, 'M': 1000,
        'IV': 4, 'IX': 9, 'XL': 40, 'XC': 90, 'CD': 400, 'CM': 900
    }
    total = 0
    i = 0
    while i < len(s):
        if i + 1 < len(s) and s[i:i+2] in mapping:
            total += mapping[s[i:i+2]]
            i += 2
        else:
            total += mapping[s[i]]
            i += 1
    return total

if __name__ == '__main__':
    s = sys.stdin.readline().strip()
    print(roman_to_int_opt(s))

import sys

def roman_to_int_best(s):
    mapping = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    total = 0
    n = len(s)
    for i in range(n - 1):
        if mapping[s[i]] < mapping[s[i+1]]:
            total -= mapping[s[i]]
        else:
            total += mapping[s[i]]
    total += mapping[s[n-1]]
    return total

if __name__ == '__main__':
    s = sys.stdin.readline().strip()
    print(roman_to_int_best(s))
